-- EPA GHG Emission Factors Hub 2025 (January 2025) and eGRID2023 revision 2 (June 2025): 360 factors added to the "EPA" 2025.1 library.
-- Generated by scripts/build-epa-hub-factors.ts from ghg-emission-factors-hub-2025.xlsx, egrid2023_data_rev2.xlsx. Do not edit by hand.
-- Per category: s1-fugitive 49, s1-mobile 7, s1-stationary 57, s2-electricity-lb 28, s2-heat 1, s3-business-travel 12, s3-commuting 9, s3-downstream-transport 7, s3-upstream-transport 7, s3-waste 183.
-- Values are converted to the canonical units (litre, kg, kWh, km, pkm, tonne.km). CO2e uses AR5 GWPs, EPA's basis.
-- eGRID subregion rows (activity type egrid_<code>) are chosen only when the record or its facility names the
-- subregion (lib/calculation/egrid-subregion.ts); otherwise the US average row applies.
-- Additive: inserts only what is missing.

INSERT INTO "factor_libraries" ("id", "name", "version", "license", "source_url", "published_at", "created_at")
